window.SAQ_PAPER_QUESTIONS["2021-2-st-george"]=[{"number":1,"title":"","stemText":"A 78-year-old female is brought to ED via ambulance from home after a neighbour found her\ncollapsed in the backyard. She is a reclusive hoarder with no known NOK. Neighbours report she rarely seeks medical attention. Her initial vital signs are :\n\nHR\n\nBP\n100/50\n\nGCS\n\nTemp 27°C","parts":[{"id":"a","label":"Part A","prompt":"In addition to environmental exposure, list (6) potential contributing factors to hypothermia in this patient. (6 marks) 1. 2. 3. 4. 5. 6."},{"id":"b","label":"Part B","prompt":"List (6) clinical features of severe hypothermia as per the categories below. (3 marks - 1⁄2 mark each) General Respiratory Cardiovascular CNS Renal GIT"},{"id":"c","label":"Part C","prompt":"Outline (4) techniques you could use in the ED to rewarm the patient. For each give the expected rate of temperature change. (4 marks) Technique Rate of change"},{"id":"d","label":"Part D","prompt":"Outline (5) changes to the ACLS algorithm which need to be made in the patient with severe hypothermia. (5 marks) 1. 2. 3. 4. 5."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Metabolic : </span><span class=\"answer-source-red\"><strong>hypothyroidism</strong></span><span class=\"answer-source-red\">, adrenal insufficiency </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Malnutrition </strong></span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Skin : any widespread erythroderma, psoriasis or exfoliative condition </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Psychiatric </span></div><div class=\"answer-line\"><strong>b)</strong><strong> </strong><strong>List (6) clinical features of severe hypothermia as per the categories below. (3 marks – </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\">mottled skin, no shivering, cyanosis </span></td></tr><tr><td><strong>Respiratory </strong></td><td><span class=\"answer-source-red\">apnoea, crepitations suggestive of pulmonary oedema </span></td></tr><tr><td><strong>Cardiovascular </strong></td><td><span class=\"answer-source-red\">bradycardia, hypotension, thready/absent peripheral pulses </span></td></tr><tr><td><strong>CNS </strong></td><td><span class=\"answer-source-red\">coma, pupillary dilation, decreased deep tendon reflexes </span></td></tr><tr><td><strong>Renal </strong></td><td><span class=\"answer-source-red\">oliguria </span></td></tr><tr><td><strong>GIT </strong></td><td><span class=\"answer-source-red\">decreased bowel sounds </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">Forced air warming blanket </span></td><td><span class=\"answer-source-red\">2°C/hr </span></td></tr><tr><td><span class=\"answer-source-red\">Warmed humidified oxygen </span></td><td><span class=\"answer-source-red\">1-1.5°C/hr </span></td></tr><tr><td><span class=\"answer-source-red\">Body cavity lavage (bladder/gastric/chest) </span></td><td><span class=\"answer-source-red\">3-6°C/hr </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Pulse check for at least 30 seconds (consider US/doppler) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Move patient gently if &lt;32° (risk of triggering VF) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No resuscitation drugs &gt;30° </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Between 30-35°double dose of ACLS drugs </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">       3 stacked shocks initially for VF, then no further shocks until &gt;30° </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">       Except in exceptional circumstances, do not cease resuscitation until &gt;32° </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"You are the ED consultant in a regional centre when a 30-year-old male presents with an isolated left elbow injury following a fall from a skateboard. He has maintained perfusion of the hand but complains of sensory loss involving the hand. A nurse has placed an IV cannula in the right arm and the patient has been kept NBM. An X-ray is performed and shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (3) pertinent findings. (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"What is the most common associated neurovascular concern associated with this injury? (1 mark)"},{"id":"c","label":"Part C","prompt":"State (4) steps in your ED management including any medications & doses. (4 marks) 1. 2. 3. 4."},{"id":"d","label":"Part D","prompt":"What are the potential long-term complications of this injury? (4 marks) 1. 2. 3. 4."}],"propPages":["asset:img9f0b820cc47f0995f1"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Fractures of the radial head and coronoid process </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Displaced bony fragments anterior to the distal humerus </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em>(= THE TERRIBLE TRIAD!) </em></span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Ulnar nerve injury </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Provide initial analgesia : </strong></span><span class=\"answer-source-red\">titrated aliquots of IV morphine 2.5mg / fentanyl 25mcg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Prepare for procedure</strong></span><span class=\"answer-source-red\"> : consent, sedation assessment, allocate staff for airway / </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">reduction, check equipment and drug doses </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Carry out reduction &amp; immobilisation</strong></span><span class=\"answer-source-red\">: provide sedation (any reasonable dose of </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">propofol / fentanyl / ketamine accepted), reduce joint with traction-countertraction, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">supination &amp; elbow flexion, place cast at 90-degree elbow flexion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Post reduction care</strong></span><span class=\"answer-source-red\"><em>: </em></span><span class=\"answer-source-red\">Obtain follow up Xray and orthopaedic review for definitive care, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">ongoing oral analgesia </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Chronic hand weakness due to nerve injury (ulnar / median) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Chronic regional pain syndrome </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Chronic / recurrent elbow instability  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Loss of ROM elbow extension </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 24-year-old female is BIBA with fever and altered mental status. Ambos report the patient has a ‘psychiatric history’, the details of which are unclear.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table below comparing neuroleptic malignant syndrome and serotonin syndrome. (6 marks)"},{"id":"b","label":"Part B","prompt":"List (3) other toxidromes associated with fever and altered mental status. (3 marks) 1. 2. 3. The patient’s examination findings are consistent with NMS. Core temperature is measured\nat 40.1°C and GCS 10."},{"id":"c","label":"Part C","prompt":"Detail (3) different methods of active cooling you would commence in the ED. (3 marks) 1. 2. 3."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><strong>Causative agent </strong></td><td><span class=\"answer-source-red\">DA agonist  </span></td><td><span class=\"answer-source-red\">5HT agonist </span></td></tr><tr><td><span class=\"answer-source-red\">eg. antipsychotics </span></td><td><span class=\"answer-source-red\">eg. SSRI, SNRI, MAOI, TCAs, </span></td><td></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">amphetamines, tramadol </span></td></tr><tr><td><strong>Time Course </strong></td><td><span class=\"answer-source-red\">Days </span></td><td><span class=\"answer-source-red\">&lt;12h </span></td></tr><tr><td><strong>Tone </strong></td><td><span class=\"answer-source-red\">Lead-pipe’ rigidity </span></td><td><span class=\"answer-source-red\">Increased LL&gt;UL </span></td></tr><tr><td><strong>Reflexes </strong></td><td><span class=\"answer-source-red\">Bradyreflexia </span></td><td><span class=\"answer-source-red\">Hyperreflexia </span></td></tr><tr><td><strong>CNS </strong></td><td><span class=\"answer-source-red\">Mutism, staring, bradykinesia </span></td><td><span class=\"answer-source-red\">Agitation, seizures </span></td></tr><tr><td><strong>« Antidote » </strong></td><td><span class=\"answer-source-red\">Bromocriptine </span></td><td><span class=\"answer-source-red\">5HT antagonists (eg. cyproheptadine) </span></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">Dantrolene </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Anticholinergic </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Sympathomimetic </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Salicylates </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Surface : tepid spray and fan, ice packs to neck/groin/axilla </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Dissipation : cool IVF (20°C), (bladder/pleural lavage) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Intubation, sedation and paralysis to prevent shivering </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 48-year-old man with a background of alcoholic cirrhosis is brought in by ambulance with massive haematemesis. You arrive just as your team are applying monitoring and securing large bore IV access in the resus bay. The patient is pale and lethargic with the following vital signs :\n\nT 35.5°C HR 120 BP 78/40 RR 28 Sats 88% RA GCS 9","parts":[{"id":"a","label":"Part A","prompt":"Outline your strategy for haemodynamic resuscitation prior to intubation. (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"State (6) strategies for minimising airway soiling and aspiration during RSI. (5 marks) 1. 2. 3. 4. 5. 6. The patient is successfully intubated."},{"id":"c","label":"Part C","prompt":"List (3) pharmacological treatments you would use in the context of this UGI bleed with a rationale for each. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Controlled hypotension</strong></span><span class=\"answer-source-red\"> : aim SBP 90-100mmHg (‘perfusing BP’) to prevent further bleed </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Judicious use of vasopressor eg. NAd infusion titrated to desired MAP  </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Head-up positioning 45 deg during preO2 and intubation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Prokinetic eg metoclopramide 20mg IV or erythromycin 250mg IV over 10 minutes </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Careful large bore NGT insertion</strong></span><span class=\"answer-source-red\"> and aspiration of gastric contents </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Double suction set-up</strong></span><span class=\"answer-source-red\"> with large bore catheter eg Ducanto if available, dedicated </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">assistant </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Avoid PPV</strong></span><span class=\"answer-source-red\"> to prevent gastric insufflation, if BVM necessary use slow, gentle technique </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">SALAD Technique with CMAC videolaryngosope – can use as DL if camera soiled </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Medication</th><th>Justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">1.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\"><strong>Ceftriaxone 1g</strong></span><span class=\"answer-source-red\"> – has been shown to reduce mortality, bacterial infection, rebleed and </span></td><td><span class=\"answer-source-red\">hospital LOS in cirrhotic patients.   </span></td></tr><tr><td><span class=\"answer-source-red\">2.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Octreotide 50 microg bolus then 50microg/hr infusion – reduces splanchnic blood flow </span></td><td><span class=\"answer-source-red\">and acid production, may prevent rebleed in variceal and nonvariceal bleed </span></td></tr><tr><td><span class=\"answer-source-red\">3.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Pantoprazole 80mg IV bolus – little evidence to support use, however, may reduce </span></td><td><span class=\"answer-source-red\">high risk stigmata of bleeding at time of scope </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"You are asked to review a 58-year-old male with a history of osteoarthritis presenting with an extensive rash and conjunctivitis following a flu-like illness the previous week. Vital signs are as follows:\n\nHR 125, BP 115 / 80, RR 24, Temp 38°C\nThe following is an image of the rash : You estimate a total body surface area involvement of 30% and make a presumptive diagnosis\n• f SJS / TENS. The patient asks what could have caused this and what his prognosis is.","parts":[{"id":"a","label":"Part A","prompt":"Aside from antibiotics, list (4) medications that are known to cause SJS/TENs (4 marks) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"List (3) components of the SCORTEN mortality score in SJS / TENS. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"State the details of your management steps for this patient: (5 marks) 1. 2. 3. 4. 5."},{"id":"d","label":"Part D","prompt":"Complete the table with (3) acute & (3) chronic complications of SJS / TENS (6 marks)"}],"propPages":["asset:img6976831f2f94261571"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Anticonvulsants eg Carbamazepine, phenytoin, lamotrigine, phenobarbitone </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Allopurinol </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Nevirapine </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Paracetamol </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">NSAIDs (especially COX2 inhibitors) </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Presence of cancer / haematologic malignancy </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Epidermal detachment &gt; 10% on day 1 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Urea &gt; 10mmol/L </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Glucose &gt; 14mmol </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Serum Bicarbonate &lt; 20mmol  </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">1.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Cessation of any suspected causative agent </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">2.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Analgesia : any reasonable opiate.  NO points for NSAID in this scenario </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">3.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Replace fluid losses : IV crystalloid / NG fluid replacement </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">4.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Skin / eye / mouth care:  Non-adherent dressings, eye ointment, topical antiseptics </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">5.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Disposition: ICU admission with dermatology/immunology involvement </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">OR Ensure thermoregulation: nurse in warm room </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">OR Sterile handling, reverse isolation procedures </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><span class=\"answer-source-red\"><strong>Severe dehydration </strong></span><span class=\"answer-source-red\">and acute malnutrition</span><span class=\"answer-source-red\"><strong> </strong></span></td><td><span class=\"answer-source-red\"><strong>Skin scarring </strong></span><span class=\"answer-source-red\">/ dyspigmentation</span><span class=\"answer-source-red\"><strong> </strong></span></td></tr><tr><td><span class=\"answer-source-red\">Infection of skin / mucous membranes / </span></td><td><span class=\"answer-source-red\">Lung disease (bronchiectasis / COPD) </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">lungs -&gt; sepsis </span></td></tr><tr><td><span class=\"answer-source-red\">ARDS   </span></td><td><span class=\"answer-source-red\">Ocular : blindness from corneal scarring, other </span></td></tr><tr><td><span class=\"answer-source-red\">GI ulceration/perforation/intussusception </span></td><td><span class=\"answer-source-red\">Joint contractures </span></td></tr><tr><td><span class=\"answer-source-red\">DIC / thromboembolism </span></td><td><span class=\"answer-source-red\">Genital scarring -&gt; phimosis, vaginal adhesions </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Shock / multi-organ failure </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 25-year-old man with a history of sickle cell disease presents with a 2-day history of non- productive cough and worsening non-pleuritic severe central chest pain radiating to both shoulders. He usually presents to your ED 1-2 times per month with complications arising from his sickle cell disease. Vitals are as follows :\n\nT\n38.0°C\n\nHR\n120\n\nBP\n110/65\n\nRR\n\nSats\n88% RA A CXR is taken and shown below :","parts":[{"id":"a","label":"Part A","prompt":"What is the MOST CONCERNING diagnosis in this patient? (1 mark)"},{"id":"b","label":"Part B","prompt":"Excluding infection, list (2) possible precipitants for this presentation. (2 marks) 1. 2."},{"id":"c","label":"Part C","prompt":"State (4) initial management priorities for this patient with justification. (4 marks) 1. 2. 3. 4."},{"id":"d","label":"Part D","prompt":"List (3) other ACUTE crises which may occur in patients with sickle cell disease. (3 marks) 1. 2. 3."},{"id":"e","label":"Part E","prompt":"List (2) indications for exchange transfusion in sickle cell crisis. (2 marks) 1. 2."}],"propPages":["asset:img0af0c53c9c53e064d6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Acute chest syndrome </span><span class=\"answer-source-red\"><em>(most common cause of death in sickle cell disease with case </em></span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em>fatality rate of 10%) </em></span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Vaso-occlusion (secondary to hypoxia, dehydration) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Hypoventilation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Atelectasis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">PE </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Optimise oxygenation</strong></span><span class=\"answer-source-red\"> (aim sats &gt;92%) – hypoxia results in sickling which worsens </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">pulmonary vascular blockage leading to worsening hypoxia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Aggressive pain management</strong></span><span class=\"answer-source-red\"> – multimodal analgesia, often require high dose opioid or </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">infusion opioid/ketamine – need to prevent hypoventilation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Initiate antibiotics </strong></span><span class=\"answer-source-red\">3rd gen cephalosporin + macrolide (cover </span><span class=\"answer-source-red\"><em>Chlamydia, mycoplasma, </em></span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em>Strep, H influenzae) </em></span><span class=\"answer-source-red\">  - febrile illness + cough = possible chest source </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Judicious IVF to treat dehydration</strong></span><span class=\"answer-source-red\"> – avoid overhydration as can worsen atelectasis, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">leads to pulmonary oedema </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Acute pain crisis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Stroke </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Dactylitis and bone infarction </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Renal infarction </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">VTE </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Priapism </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pregnancy-related complications </span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Neurological presentations : TIA, stroke, seizures </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Lung involvement : PaO2 &lt;65 with FiO2 0.6 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Sequestration syndromes </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Priapism </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">(Cameron Box 13.1.6 p 501) </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 12-month-old girl is brought to your Emergency Department with two days of vomiting,\nfevers, rhinorrhoea and lethargy. Her vitals are as follows :\n\nHR 170, RR 45, SaO2 99%RA, Temp 39.5°C","parts":[{"id":"a","label":"Part A","prompt":"List (4) potential causes for this child’s signs and symptoms. (4 marks) 1. 2. 3. 4. A VBG is performed :\n\npH\n7.30\n\npCO2\n\nPO2\n\nHCO3\n13.4\n\nBE -\n9.7\n\nNa\n110\n\nK\n7.5\n\nCl\nIonised Ca 1.16\n\nGlucose\n3.0\n\nLactate\n2.2\n\nCreatinine\n\nHb\n145 You assess the patient as having moderate to severe dehydration."},{"id":"b","label":"Part B","prompt":"List (4) abnormalities in this VBG and state at least (2) actions you will undertake to address each. (8 marks) Abnormality Actions"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\"><strong>UTI</strong></span><span class=\"answer-source-red\"> - should be highest differential </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Viral illness </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Meningitis  </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">First presentation of DKA  </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Other differential although significantly less common : bacteraemia, NAI with ICH </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\"><em>Not gastroenteritis given no reported diarrhoea</em></span><span class=\"answer-source-red\">  </span></td></tr><tr><td colspan=\"2\">A VBG is performed and shown below :</td></tr><tr><td>pH</td><td>7.30</td></tr><tr><td>pCO2</td><td>24</td></tr><tr><td>PO2</td><td>39</td></tr><tr><td>HCO3</td><td>13.4</td></tr><tr><td>BE -</td><td>9.7</td></tr><tr><td>Na</td><td>110</td></tr><tr><td>K</td><td>7.5</td></tr><tr><td>Cl</td><td>81</td></tr><tr><td>Ionised Ca</td><td>1.16</td></tr><tr><td>Glucose</td><td>3.0</td></tr><tr><td>Lactate</td><td>2.2</td></tr><tr><td>Creatinine</td><td>76</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><span class=\"answer-source-red\">Hyperkalaemia </span></td><td><span class=\"answer-source-red\">Cardiac monitoring </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">If ECG abnormal give calcium gluconate 0.1mmol/kg IV over 3-5 </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">minutes </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Insulin actrapid 0.1units/kg IV and dextrose 10% 5ml/kg IV </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Nebulised salbutamol 2.5mg </span></td></tr><tr><td><span class=\"answer-source-red\">Hypoglycaemia </span></td><td><span class=\"answer-source-red\">2mL/kg 10% dextrose IV </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Consider reduced dose insulin for hyperK </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Monitor BSL q15min </span></td></tr><tr><td><span class=\"answer-source-red\">Hyponatraemia </span></td><td><span class=\"answer-source-red\">Paired S and U osmol, U Na </span></td></tr><tr><td><span class=\"answer-source-red\">(likely hypovolaemic +/- </span></td><td><span class=\"answer-source-red\">Give 0.9% saline with 5% dextrose for maintenance </span></td></tr><tr><td><span class=\"answer-source-red\">SIADH) </span></td><td><span class=\"answer-source-red\">Check S.Na q4-6h, ensure no more than 8mmol/L rise in 24h </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Monitor for CNS symptoms – 3mL/kg 3% saline if seizures </span></td></tr><tr><td><span class=\"answer-source-red\">AKI – likely prerenal </span></td><td><span class=\"answer-source-red\">0.9% sodium chloride bolus 10ml/kg, aiming for cap return &lt;3secs and </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">decrease in HR to below 140 </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Then maintenance as above </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Avoid nephrotoxins (eg NSAIDs) </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 21-year-old female with a VP shunt is brought into to your tertiary Emergency Department by her family with a few days of worsening global headache, nausea and lethargy. Her family have noticed she seemed drowsier and more confused in the past 24 hours. The shunt was\nplaced 10 years ago following an intracranial haemorrhage.\nObs on arrival :\n\nT\n37.9\n\nHR\n\nBP\n130/70\n\nRR\n\nSats\n98%RA\n\nGCS\nE3V4M5 = 12 (baseline 15)","parts":[{"id":"a","label":"Part A","prompt":"What is your main concern? (1 mark)"},{"id":"b","label":"Part B","prompt":"List and justify (3) specific investigations you would organise to evaluate the cause of this presentation. (6 marks) Investigation Justification On return from radiology the nurse rushes up to inform you that the patient’s GCS has\ndropped to 9 and she is becoming more bradycardic and hypertensive."},{"id":"c","label":"Part C","prompt":"State (5) strategies for managing this patient’s raised ICP including doses and endpoints where appropriate. (5 marks) 1. 2. 3. 4. 5."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Shunt failure with worsening hydrocephalus and raised ICP </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">(Infection is possible but a secondary issue) </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><span class=\"answer-source-red\">Shunt series </span></td><td><span class=\"answer-source-red\">Assess for shunt migration, fracture, kinking, </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">disconnection </span></td></tr><tr><td><span class=\"answer-source-red\">Non-contrast CTB </span></td><td><span class=\"answer-source-red\">Assess for ventricular enlargement compared with any </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">previous scan</span><span class=\"answer-source-red\"><strong> </strong></span><span class=\"answer-source-red\">suggesting obstruction (up to 30% may </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">lack this finding) </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Assess for slit ventricle syndrome from over drainage </span></td></tr><tr><td><span class=\"answer-source-red\">V-P shunt tapping or LP (if </span></td><td><span class=\"answer-source-red\">Obtain CSF to assess for infection, measure shunt </span></td></tr><tr><td><span class=\"answer-source-red\">communicating HC) – </span><span class=\"answer-source-red\"><strong>in </strong></span></td><td><span class=\"answer-source-red\">pressure </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\"><strong>consultation with neuroSx</strong></span><span class=\"answer-source-red\"> </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Positioning</strong></span><span class=\"answer-source-red\"> : 30 degrees head-up, avoid neck flexion/rotation/compression </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Intubation and controlled hyperventilation</strong></span><span class=\"answer-source-red\"> – temporising measure aiming pCO2 30-</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">35mmHg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Adequate sedation</strong></span><span class=\"answer-source-red\"> eg fentanyl/propofol </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Osmotic diuresis</strong></span><span class=\"answer-source-red\"> - mannitol 1g/kg over 20 minutes OR hypertonic (3%) saline 3mL/kg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">slow push </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Tap shunt reservoir</strong></span><span class=\"answer-source-red\"> (in consultation with neuroSx) if evidence of distal occlusion </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You are the consultant working in a regional ED when asked to review a 22-year-old female with acute onset headache & vomiting. She appears tired but has normal vital signs and no neurological deficits on examination. She has a history of migraines, PCOS and obesity.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table of differential diagnoses - apart from migraine - and provide key investigation(s). (5 marks) Differential diagnoses Key investigation(s) She is treated for acute migraine with chlorpromazine in ED Short Stay with some improvement & is discharged home. The patient represents the following day following worsening headache & reduced GCS Neuroimaging is undertaken :"},{"id":"b","label":"Part B","prompt":"What does the CT reveal? (1 mark)"},{"id":"c","label":"Part C","prompt":"List and explain (4) types of cognitive biases known to occur in emergency medicine (8 marks) Cognitive bias Explanation"},{"id":"d","label":"Part D","prompt":"State (4) means by which cognitive bias in emergency medicine can be minimised (4 marks) 1. 2. 3. 4."}],"propPages":["asset:imgb5fc26d2dff05af4ef"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><span class=\"answer-source-red\">SAH </span></td><td><span class=\"answer-source-red\">CTB (&lt; 6hrs) +/- LP for xanthochromia </span></td></tr><tr><td><span class=\"answer-source-red\">Venous sinus thrombosis </span></td><td><span class=\"answer-source-red\">CT venogram </span></td></tr><tr><td><span class=\"answer-source-red\">Carotid / vertebral artery dissection </span></td><td><span class=\"answer-source-red\">CT angiogram arch-cow </span></td></tr><tr><td><span class=\"answer-source-red\">Meningitis </span></td><td><span class=\"answer-source-red\">CSF MCS </span></td></tr><tr><td><span class=\"answer-source-red\">Benign intracranial HTN </span></td><td><span class=\"answer-source-red\">LP with opening pressure </span></td></tr><tr><td><span class=\"answer-source-red\">Reversible cerebral vascoconstriction </span></td><td><span class=\"answer-source-red\">MRA / CTA </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">syndrome </span></td></tr><tr><td colspan=\"2\">She is treated for acute migraine with chlorpromazine in ED Short Stay with some</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">CT venogram shows extensive filling defect anterior 2/3 of superior sagittal sinus </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">consistent with CVST </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">MANY – accept any brief sensible explanation.  Common in ED : </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Search satisficing / premature closure</strong></span><span class=\"answer-source-red\"> : calling off a search once a positive finding/ </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">diagnosis has been attained and ignoring subsequent relevant information or ceasing </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">further workup </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Anchoring bias </strong></span><span class=\"answer-source-red\">: </span><span class=\"answer-source-red\"><strong> </strong></span><span class=\"answer-source-red\">maintaining initial impression despite evidence pointing to the </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">contrary </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Availability bias</strong></span><span class=\"answer-source-red\"> : the tendency to judge the likelihood of disease by the ease with which </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">relevant examples come to mind, usually recent events with an emotions component </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Confirmation bias </strong></span><span class=\"answer-source-red\"> : the tendency to look for confirming evidence to support a diagnosis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">and ignoring/not seeking refuting evidence </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Other : diagnostic momentum, framing effect, fundamental attribution error, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">overconfidence bias, base-rate neglect, gambler’s fallacy… </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">1.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Formal education &amp; training of cognitive bias &amp; errors </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">2.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Use of forced cognitive strategies / cognitive stop points </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">3.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Cognitive unloading; eg use of medical calculators / clinical pathways or guidelines </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">4.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Address system factors that increase cognitive errors eg minimise interruptions </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"You are a consultant working an evening shift in a tertiary ED. You have just received a\nbatphone call regarding a 40-year-old female with a suspected drug overdose. Paramedics\nwere unable to identify the tablets in her home. The patient arrives shortly after and on transfer from the stretcher to the resus bed, has a generalised tonic-clonic seizure.","parts":[{"id":"a","label":"Part A","prompt":"List (4) toxicological causes of seizures from (4) different drug categories. (4 marks) 1. 2. 3. 4. The seizure self-terminates after a few seconds. The following ECG is obtained :"},{"id":"b","label":"Part B","prompt":"List (3) relevant findings and state your conclusion. (4 marks) 1. 2. 3. Conclusion :_________________________________________________________________ The patient’s GCS remains 3/15 and you decide to intubate.\nCurrent observations :\n\nGCS 3/15\n\nHR 100\n\nBP 80/50\n\nRR 24\n\nSats 100% on 15L"},{"id":"c","label":"Part C","prompt":"Outline (4) important RSI and peri-intubation considerations for this patient. Include drug doses and endpoints where relevant. (4 marks) 1. 2. 3. 4."}],"propPages":["asset:img47be3185adb2ac08bc"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Anticonvulsants: carbamazepine, topiramate </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Antidepressants: bupropion, (es)citalopram, (des)venlafaxine, TCAs </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Antimalarials: (hydroxy)chloroquine, quinine </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Antipsychotics: olanzapine, quetiapine, atypicals </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Baclofen </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Isoniazid </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">OHA </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Local anaesthetic agents: lignocaine </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Opiates: tramadol </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Salicylates </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Sympathomimetics: cocaine, amphetamines </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Withdrawal: alcohol, benzos, GHB </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Tachycardia- rate around 100 bpm </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Right axis deviation of the QRS in aVR: terminal R wave &gt; 3mm in aVR </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">R/S ratio &gt; 0.7 in aVR </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Widened QRS 140-160 ms </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Prolonged QT </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Conclusion :  sodium channel blocker overdose eg TCA </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">100mmol IV bolus, commence NAd IV infusion at 5mcg/min and titrate to MAP &gt; </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">65mmHg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Consider pre-RSI benzodiazepine to lower seizure threshold </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Avoid prolonged apnoea and hypercarbia : most experienced intubator </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Reduce dose induction agent given obtundation and haemodynamic instability </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Hyperventilate to maintain pH 7.5-7.55 (PaCO2 25-30mmHg) </strong></span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Sedate with benzodiazepine or propofol to reduce seizure threshold </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em><strong>(Need 2 bold for full marks, otherwise max 2/4) </strong></em></span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 65-year-old man presents with sudden onset painless blurred vision in the left eye.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table below listing (5) important causes of painless monocular visual impairment in this patient. For each, give a relevant feature of HPI or PMHx which supports the diagnosis. (5 marks) Differential Diagnosis History"},{"id":"b","label":"Part B","prompt":"List and justify (4) important features of examination you would undertake. (4 marks) Examination Justification Following your initial history and examination, you perform an ocular ultrasound of the left eye as shown below :"},{"id":"c","label":"Part C","prompt":"List (2) pertinent findings and the likely diagnosis. (3 marks) 1. 2. Diagnosis : __________________________________________________________________"}],"propPages":["asset:imgbdbc65e46a7730c032","asset:img0db836675269f66afb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\"><strong>Retinal detachment</strong></span><strong> </strong></td><td><span class=\"answer-source-red\">A “curtain” coming down </span></td></tr><tr><td><span class=\"answer-source-red\">Previous or family history of retinal detachment </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Previous severe eye injury or surgery </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Myopia</span></td><td></td></tr><tr><td><span class=\"answer-source-red\"><strong>Vitreous haemorrhage / detachment </strong></span></td><td><span class=\"answer-source-red\">Flashes and floaters </span></td></tr><tr><td><span class=\"answer-source-red\">Hx of diabetic retinopathy </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Hx of trauma </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">ARMD </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">CRAO </span></td><td><span class=\"answer-source-red\">Hx of AF </span></td></tr><tr><td><span class=\"answer-source-red\">Vascular risk factors </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Previous TIA/CVA</span><span class=\"answer-source-red\"><strong> </strong></span></td><td></td></tr><tr><td><span class=\"answer-source-red\">CRVO </span></td><td><span class=\"answer-source-red\">Hx of metabolic syndrome </span></td></tr><tr><td><span class=\"answer-source-red\">Glaucoma </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">GCA </span></td><td><span class=\"answer-source-red\">Headache/jaw claudication </span></td></tr><tr><td><span class=\"answer-source-red\">Hx of PMR </span></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Visual acuity each eye </strong></span><span class=\"answer-source-red\">: important to document baseline and confirm unilateral </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">pathology </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Visual fields </strong></span><span class=\"answer-source-red\">: abnormality may suggest retinal detachment, branch RAO or RVO</span><span class=\"answer-source-red\"><strong> </strong></span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pupillary responses and RAPD :  large retinal detachment, CRAO, CRVO </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Ocular pressure : ? </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Slit lamp exam : may detect vitreous pathology </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Red reflex : may see shadows/cobwebs, if reduced/dark consider vitreous haemorrhage) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Fundoscopy</strong></span><span class=\"answer-source-red\"> : fundal pallor/cherry red spot (CRAO), macular oedema/flame </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">haemorrhage (CRVO), large retinal detachment</span><span class=\"answer-source-red\"><strong> </strong></span></div><div class=\"answer-line\"><span class=\"answer-source-red\">General neurologic examination </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Temporal artery tenderness : GCA </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Hazy, echogenic membranes and material in posterior chamber </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No evidence of detached retina </span></div><div class=\"answer-line\"><strong>d)</strong><strong> </strong><strong>State the likely diagnosis. (1 mark) </strong></div><div class=\"answer-line\"><span class=\"answer-source-red\">Vitreous detachment </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"Your registrar asks you to review a 10-week-old female who has been vomiting since 4 weeks\n• f age. Exprem 36/40, birth weight 2.88kg, current weight 2.78kg. No urine output past 24\nhours. Vitals :\n\nHR\n168\n\nRR\n\nSats\n90% RA prior to adding NP oxygen","parts":[{"id":"a","label":"Part A","prompt":"What is the estimated weight this child should be at 10 weeks? A VBG is performed :\n\npH\n7.8\n\nPO2\n\npCO2\n\nBE\n-30\n\nHCO3\n79.8\n\nK+\n2.0\n\nBSL\n2.9\n\nLactate\n3.7"},{"id":"b","label":"Part B","prompt":"Interpret the VBG. (5 marks) 1. 2. 3. 4. 5."},{"id":"c","label":"Part C","prompt":"What is your diagnosis?"},{"id":"d","label":"Part D","prompt":"Outline your acute management of this baby. (5 marks) 1. 2. 3. 4. 5."}],"propPages":["asset:img435c231887d8136fb0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>pH</td><td>7.8</td></tr><tr><td>PO2</td><td>32</td></tr><tr><td>pCO2</td><td>65</td></tr><tr><td>BE</td><td>-30</td></tr><tr><td>HCO3</td><td>79.8</td></tr><tr><td>K+</td><td>2.0</td></tr><tr><td>BSL</td><td>2.9</td></tr><tr><td>Lactate</td><td>3.7</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Vitals :</div><div class=\"answer-line\">HR</div><div class=\"answer-line\">168</div><div class=\"answer-line\">RR</div><div class=\"answer-line\">Sats</div><div class=\"answer-line\">90% RA prior to adding NP oxygen</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>a)</strong><strong> </strong><strong>What is the estimated weight this child should be at 10 weeks?</strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">32</div><div class=\"answer-line\">65</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"You review an 84-year-old male presenting after a witnessed mechanical fall from standing\nwhilst attending hospital pathology. He has minor abrasions to his hands & knees and denies any significant pain. He is able to mobilise with some assist and is triaged Category 4 to fast track. Past history includes IHD, atrial fibrillation, hypertension, stage 4 chronic kidney disease and rheumatoid arthritis. Ex-smoker (30 pack-year history). His medications include warfarin,\nprednisone 5mg daily, candesartan & pantoprazole.\n\nVital signs are as follows:\n\nTemp 37.4°C, HR 104, BP 160 / 90, RR 22, Sats 94% RA, GCS 15\nA CXR has been ordered and is available at the time of your review:","parts":[{"id":"a","label":"Part A","prompt":"What does the CXR demonstrate? (2 marks) 1. 2."},{"id":"b","label":"Part B","prompt":"Complete the table below with (4) potential underlying diagnoses for the above CXR for this patient, and a specific treatment for each diagnosis provided. (8 marks) Diagnosis Treatment"},{"id":"c","label":"Part C","prompt":"State (4) factors that may contribute to inappropriate triage categories and a strategy for addressing each (8 marks) Factor Strategy"}],"propPages":["asset:img64885acd9efec95156"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Dense opacification of mid-lower zone R hemithorax obscuring R hemidiaphragm – likely </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">to represent pleural effusion</span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">Insertion of intercostal catheter,  </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Haemothorax </span></td><td><span class=\"answer-source-red\">reversal of anticoagulation </span></td></tr><tr><td><span class=\"answer-source-red\">Malignancy  </span></td><td><span class=\"answer-source-red\">Chemotherapy / radiotherapy </span></td></tr><tr><td><span class=\"answer-source-red\">Rheumatoid / auto-immune </span></td><td><span class=\"answer-source-red\">Drainage +/- systemic steroid / </span></td></tr><tr><td><span class=\"answer-source-red\">immunosuppressives </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">CCF </span></td><td><span class=\"answer-source-red\">IV diuresis / nitrates  </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Language / communication barriers:  Use of accredited translators or multi-lingual staff </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">to assist at triage  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Inadequate assessment at triage eg failure to recognise significant medical history: </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Review of EMR / clarification with GP pharmacy / NOK </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Failure to measure or appreciate abnormalities in vital signs : Policies to mandate vital </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">signs in high risk / elderly patients </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Failure to re-triage with deterioration in condition: Systems to ensure nursing review of </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">patients waiting beyond set time eg 2 hours.  Signage to encourage raising concerns of </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">patient deterioration to triage / nursing staff. </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 29-year-old female at 33/40 gestation is brought to your Emergency Department following\nan MVA. Mechanism car vs tree, travelling 50km/hr. She was restrained and airbags deployed and now complains of abdominal pain.","parts":[{"id":"a","label":"Part A","prompt":"Other than MVA what are the (2) other most common causes of trauma in pregnancy? (2 marks) 1. 2."},{"id":"b","label":"Part B","prompt":"List (5) pregnancy-specific complications of trauma and provide a positive clinical or investigation finding for each (5 marks) Complication Clinical/Investigation Finding You notice a seat-belt bruise across her lower abdomen."},{"id":"c","label":"Part C","prompt":"What is the significance of this? (1 mark)"},{"id":"d","label":"Part D","prompt":"List (4) relevant facts relating to the utility of bedside ultrasound in the assessment of the pregnant trauma patient. (4 marks) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Falls </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Domestic Violence </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">Pelvic pain, uterine contractions, PV bleeding, </span></td><td></td></tr><tr><td><span class=\"answer-source-red\"><strong>foetal distress on CTG</strong></span><span class=\"answer-source-red\"> </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Direct foetal trauma </span></td><td><span class=\"answer-source-red\">No FM/FHB on CTG/US </span></td></tr><tr><td><span class=\"answer-source-red\">Ruptured uterus </span></td><td><span class=\"answer-source-red\"><strong>Maternal shock</strong></span><span class=\"answer-source-red\">, palpable foetal parts, difficulty </span></td></tr><tr><td><span class=\"answer-source-red\">defining uterus on palpation, +ve FAST </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Early labour </span></td><td><span class=\"answer-source-red\">Increasing regularity contraction, cervix &lt;3cm on </span></td></tr><tr><td><span class=\"answer-source-red\">PROM </span></td><td><span class=\"answer-source-red\">Vaginal loss of liquor, confirmed by alkaline by </span></td></tr><tr><td><span class=\"answer-source-red\">nitrazine test (or Amnisure ROM test) </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Feto-maternal haemorrhage </span></td><td><span class=\"answer-source-red\">Positive Kleihauer test </span></td></tr><tr><td><span class=\"answer-source-red\">Amniotic fluid embolism </span></td><td><span class=\"answer-source-red\">Obstructive shock, signs of right heart strain on </span></td></tr><tr><td><span class=\"answer-source-red\">US/ECG, DIC </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Placental or umbilical cord laceration </span></td><td><span class=\"answer-source-red\">Positive Kleihauer test </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Incorrect seatbelt placement over abdomen rather than thighs will increase likelihood of </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">foetal injury. </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Free fluid in the abdomen may indicate blood or liquor from uterine rupture </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Can assess : FHR, activity, presentation/lie, liquor volume, placental position </span><span class=\"answer-source-red\"><em>(accept 2 of </em></span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em>these) </em></span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 72-year-old fisherman is retrieved from the ocean after being swept off a rock-ledge. He\nhas a history of type 2 diabetes and hypertension. He has been bought directly to your ED\nby road. On arrival to resus, your team applies monitoring and obtains IV access. Initial vitals are as follows :\n\nTemp 30°C, HR 120, BP 90/ 55, RR 28, Sats 94% on 15L/min O2 via NRB\n\nGCS 13, BSL 3.2\nThere is no external evidence of major head trauma, no gross limb deformity and he can move all limbs. He appears to be tiring.","parts":[{"id":"a","label":"Part A","prompt":"State details of your FIRST (4) steps in management. (4 marks) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"Name (2) risk factors for drowning by each category (4 marks) Sociodemographic Underlying medical condition"},{"id":"c","label":"Part C","prompt":"In addition to hypothermia, list (4) complications of drowning. (4 marks) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">1.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\"><strong>Address haemodynamics</strong></span><span class=\"answer-source-red\"> : judicious crystalloid boluses aiming systolic &gt; 100, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">progress to push does vasopressors if inadequate response </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">2.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\"><strong>Respiratory support</strong></span><span class=\"answer-source-red\"> : commence NIV (CPAP / BiPAP) high PEEP 12-15 cmH2O and </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">high FiO2 titrated to Sats &gt; 94%.  Plan for intubation in event of further </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">deterioration. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">3.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\"><strong>Warm patient</strong></span><span class=\"answer-source-red\"> :  remove wet clothes, adequately dry, start active external warming, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">give IV fluids through warmer </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">4.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\"><strong>Address hypoglycaemia</strong></span><span class=\"answer-source-red\"> : 25-50mls 50% dextrose aim BSL &gt; 5, monitor BSL hourly </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Sociodemographic</strong></span><span class=\"answer-source-red\">: inadequately supervised infant / male aged 16-24 / risk taking </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">behaviour / drug or ETOH intoxication </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Ischaemic cardiomyopathy </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Electrolyte derangement -&gt; arrythmia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">AKI </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Multi-organ failure </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>(Need bold for full marks otherwise max score 2/4) </strong></span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em>(Diuretics : IV acetazolamide / frusemide – decrease CSF production by choroid plexus – used </em></span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em>in normal pressure hydrocephalus)</em></span><span class=\"answer-source-red\"> </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 72-year-old man from home with his wife, is brought in by ambulance after a fall. He reports losing balance and falling forward, hitting his head on a window-sill then landing prone on the ground. He has full recall of events and complains of neck pain. Only past medical history is early Parkinsons Disease. On brief initial examination his obs are unremarkable and there does not appear to be any significant neuro deficit. He is immobilised in a hard C-spine collar. You arrange urgent CT brain and C-spine, a section of which shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (2) concerning features on the CT image. (2 marks) 1. 2. This appears to be the only sequelae of trauma on examination and relevant imaging."},{"id":"b","label":"Part B","prompt":"List (5) specific complications you might anticipate from this injury and state how you would mitigate / manage each if required. Give drug doses and endpoints where relevant. (10 marks) Complication Management"}],"propPages":["asset:imgd7f3ed2f4e69586f50"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>1. </strong><span class=\"answer-source-red\">Type II dens fracture </span></div><div class=\"answer-line\"><strong>2. </strong><span class=\"answer-source-red\">Posterior displacement of approximately 3mm </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><span class=\"answer-source-red\">Worsening prevertebral </span></td><td><span class=\"answer-source-red\">Careful emergent intubation, ideally </span></td></tr><tr><td><span class=\"answer-source-red\">oedema/hematoma occluding airway </span></td><td><span class=\"answer-source-red\">fibreoptic, but shown to be safe with VL RSI </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">with MILS/bougie/most experienced operator </span></td></tr><tr><td><span class=\"answer-source-red\">Respiratory failure – C2 high risk</span><span class=\"answer-source-red\"><strong> </strong></span></td><td><span class=\"answer-source-red\">Intubation (as above) if VC &lt; 30% predicted, </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">poor cough – oxygenation and ventilation to </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">normoxia/normocapnia </span></td></tr><tr><td><span class=\"answer-source-red\">Neurogenic shock – injury above T6 </span></td><td><span class=\"answer-source-red\">Art line, judicious fluid resus, early </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">vasopressor infusion (noradrenaline) titrated </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">to MAP &gt;85-90mmHg, atropine for </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">bradycardia to HR &gt; 60bpm </span></td></tr><tr><td><span class=\"answer-source-red\">Cervical myelopathy – cord syndrome </span></td><td><span class=\"answer-source-red\">Appropriate C-spine immobilisation (Phile, </span></td></tr><tr><td><span class=\"answer-source-red\">from vertebral compression </span></td><td><span class=\"answer-source-red\">Miami J, Aspen) with strict spinal precautions </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">(entire spine), careful logroll </span></td></tr><tr><td><span class=\"answer-source-red\">Pressure areas  </span></td><td><span class=\"answer-source-red\">Q2H repositioning, air mattressi </span></td></tr><tr><td><span class=\"answer-source-red\">Urinary retention </span></td><td><span class=\"answer-source-red\">IDC insertion </span></td></tr><tr><td><span class=\"answer-source-red\">Aspiration due to gastroparesis, reduced </span></td><td><span class=\"answer-source-red\">Early NGT insertion, NBM </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">GOS tone </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"You are the ED consultant at a metropolitan tertiary hospital. A nurse has asked you to review a 60-year-old female presenting with shortness of breath & lethargy who is triaged category 2 to the resus room. The patient appears unwell, does not speak English and limited collateral history is available from an acquaintance. She arrived on holidays from China 10 days prior\nand has become unwell over 3 days with vomiting, lethargy, and dyspnoea.\n\nVital signs are as follows:\n\nTemp 37.4°C, HR 180, BP 100/50, RR 30, SaO2 difficult to obtain, GCS 12\nA VBG is performed :\n\npH\n6.8\n\npCO2\n\nHCO3\n\nNa\n124\n\nK\n7.9\n\nCl\n\nLactate\n\nGlucose\n> 40","parts":[{"id":"a","label":"Part A","prompt":"Give your overall impression of this VBG with the most likely diagnosis. (2 marks) Overall impression Diagnosis"},{"id":"b","label":"Part B","prompt":"List (4) other investigations you would order with a rationale for each. (4 marks) Investigation Rationale"},{"id":"c","label":"Part C","prompt":"State your treatment priorities for this patient in the first hour of their ED stay including drug doses/routes where relevant. (4 marks) 1. 2. 3. 4."},{"id":"d","label":"Part D","prompt":"Complete the table below listing (4) barriers of care for culturally & linguistically diverse patients in the ED, with a means of reducing each"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Profound HAGMA with attempted respiratory compensation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Life-threatening hyperK secondary to acidosis +/- AKI </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Diagnosis : severe DKA with associated shock state </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">ECG  : seek tachyarrhythmia, cardiac effects of hyperkalaemia </span></td><td><span class=\"answer-source-red\">Serum ketones : confirm DKA, monitor for clearance  </span></td></tr><tr><td><span class=\"answer-source-red\">EUC : exclude AKI, confirm hyperkalaemia on VBG </span></td><td><span class=\"answer-source-red\">Blood cultures - infective trigger </span></td></tr><tr><td><span class=\"answer-source-red\">CXR : tachypnoea </span><span class=\"answer-source-red\"><em>(though likely secondary to metabolic acidosis)</em></span><span class=\"answer-source-red\">, seek evidence resp </span></td><td><span class=\"answer-source-red\">infection / cardiomegaly / aspiration </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Restore perfusion </strong></span><span class=\"answer-source-red\">: IV crystalloid 1L over 1hr +/- vasopressor if inadequate response </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Treat hyperkalaemia</strong></span><span class=\"answer-source-red\">: Should respond to fluid resus but is significant in this patient </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">therefore give 10mmol 10mL IV calcium gluconate  + 10 units IV actrapid / novorapid </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Treat ketoacidosis</strong></span><span class=\"answer-source-red\">:  Fast acting insulin infusion 0.1U/kg/hr (actrapid / novorapid) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Respiratory support : HFNC FiO2 titrated to Sats &gt; 92% increasing flow rate as high as </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">patient can tolerate </span><span class=\"answer-source-red\"><em>(reduces deadspace and WOB) </em></span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Treat vomiting : Ondansetron 4-8mg IV / metoclopramide 10mg IV </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em><strong>NO MARKS FOR INTUBATION unless appropriate indication stated, want to avoid this </strong></em></span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><em><strong>where possible – mental status should improve over time with resuscitation </strong></em></span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><span class=\"answer-source-red\">Language </span></td><td><span class=\"answer-source-red\">Access to 24hr phone interpreter </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">Multilingual signage in ED and patient information </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">handouts </span></td></tr><tr><td><span class=\"answer-source-red\">Cost / financial concerns </span></td><td><span class=\"answer-source-red\">Insurance &amp; finance liaison officers within hospital </span></td></tr><tr><td><span class=\"answer-source-red\">Fear of hospitals / institutions </span></td><td><span class=\"answer-source-red\">Presence of cultural safety staff eg Indigenous health </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">liaison </span></td></tr><tr><td><span class=\"answer-source-red\">Concerns over cultural judgement </span></td><td><span class=\"answer-source-red\">Staff education in cultural safety </span></td></tr><tr><td><span class=\"answer-source-red\">Gender concerns </span></td><td><span class=\"answer-source-red\">Staffing availability of both male &amp; female medical &amp; </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">nursing staff  </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 2-year-old boy is brought to your Emergency Department not weight-bearing on his left leg. This has been noted for the past five days and he seems to be progressively more reluctant to walk. He is otherwise well with no past medical history and immunisations are UTD. Vitals are : T 38.5°C, HR 150, RR 30, Sats 99%RA","parts":[{"id":"a","label":"Part A","prompt":"List (5) potential causes for this boy’s signs and symptoms. (5 marks) 1. 2. 3. 4. 5."},{"id":"c","label":"Part C","prompt":"List (3) relevant findings and state a conclusion. (4 marks) 1. 2. 3. Conclusion : ________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List (3) further investigations you would order and provide rationale for each. (3 marks) Investigation Rationale"}],"propPages":["asset:img54c00079464a14d698"],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["ray of the L ankle is performed :"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Toddlers spiral fracture </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Acute viral induced myositis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Rarer differentials : malignancy eg Ewing’s sarcoma, post infectious arthritis, HSP </span></div><div class=\"answer-line\"><strong>X-ray of the L ankle is performed and shown below : </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Bony erosion of the distal medial aspect of the tibia with a moth-eaten appearance</strong></span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No fracture </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No joint effusion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Conclusion : likely osteomyelitis</strong></span><span class=\"answer-source-red\"> (ddx malignancy)</span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">Raised WCC, platelets as inflammatory markers </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">CRP </span></td><td><span class=\"answer-source-red\">Significant elevation may suggest bacteraemia, trend will enable </span></td></tr><tr><td><span class=\"answer-source-red\">monitoring of recovery </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Blood cultures </span></td><td><span class=\"answer-source-red\">To exclude bacteraemia as trigger for septic arthritis, direct </span></td></tr><tr><td><span class=\"answer-source-red\">antibiotic therapy </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">Blood film </span></td><td><span class=\"answer-source-red\">If concern for haematological malignancy </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 65-year-old obese male patient with a background of asthma is in the ED resus bay post-\nintubation for sepsis and respiratory failure. A central line and arterial line have been successfully inserted. Appropriate fluid resuscitation and antibiotic therapy has been given. Noradrenaline has been commenced and is running at a rate of 30mL/hr of 4mg in 50mL dextrose via syringe driver. He has infusions of fentanyl and propofol running. He requires transfer to the radiology department for CT imaging which is 5-minutes’ walk from the ED.","parts":[{"id":"a","label":"Part A","prompt":"What are the minimum standards of monitoring required for the safe transfer of this\npatient (2 marks - 1⁄2 mark each)\n1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"Outline (4) other critical transport equipment required. (4 marks) 1. 2. 3."},{"id":"d","label":"Part D","prompt":"List (4) specific causes you would consider in this patient and provide a solution for each. (4 marks) Cause Solution"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["You are remoted from the ED when the HIGH AIRWAY PRESSURE alarm sounds on the ventilator."],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\">O</span><span class=\"answer-source-red\">2</span><span class=\"answer-source-red\"> sats </span></td></tr><tr><td><strong>2. </strong></td><td><span class=\"answer-source-red\">Waveform ETCO</span><span class=\"answer-source-red\">2</span><span class=\"answer-source-red\"> </span></td></tr><tr><td><strong>3. </strong></td><td><span class=\"answer-source-red\">ECG </span></td></tr><tr><td><strong>4. </strong></td><td><span class=\"answer-source-red\">(Invasive) BP </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Infusion devices with adequate battery life </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Sufficient medication</strong></span><span class=\"answer-source-red\"> : consider spare or increase concentration, rescue (paralysis, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">ACLS) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Rescue equipment</strong></span><span class=\"answer-source-red\"> : self-inflating BVM, intubation equipment, defibrillator </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Rescue medication : paralysis, ACLS meds, push-dose pressor </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Emergency bolus fluids </span></div><div class=\"answer-line\">You are remoted from the ED when the HIGH AIRWAY PRESSURE alarm sounds on the</div><div class=\"answer-line\">ventilator.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">ETT occlusion by secretions </span></td><td><span class=\"answer-source-red\">Suction </span></td></tr><tr><td><span class=\"answer-source-red\">Breath stacking </span></td><td><span class=\"answer-source-red\">Disconnect from vent, reduce RR </span></td></tr><tr><td><span class=\"answer-source-red\">Reduced chest wall compliance due to obesity </span></td><td><span class=\"answer-source-red\">Elevate head of bed </span></td></tr><tr><td><span class=\"answer-source-red\">Tension pneumothorax </span></td><td><span class=\"answer-source-red\">Chest decompression </span></td></tr><tr><td><span class=\"answer-source-red\">Bronchospasm </span></td><td><span class=\"answer-source-red\">Intensify bronchodilator therapy (neb and IV) </span></td></tr><tr><td>No marks for general causes such as ETT malposition, biting, equipment failure,</td><td></td></tr><tr><td>dyssynchrony</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 74-year-old man is brought in by ambulance having received multiple shocks from his ICD\nat home. He has a history of CABG and STEMI 10 years prior, at which time the ICD was placed. He had been monitored in sinus rhythm during his transfer to hospital but appeared pale and drowsy shortly after being transferred onto the resus bed. Vitals are as follows :\n\nHR\n200/min (thready central pulse)\n\nBP\nunrecordable\n\nRR\n\nSaO2 98% on RA\nHis 12-lead ECG is shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (3) salient findings on this ECG and state a conclusion (4 marks) 1. 2. 3. Conclusion : ________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List (4) potential underlying triggers for this tachyarrhythmia. (4 marks) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"State (4) key priorities of management (include drug doses and rate of delivery where relevant). (4 marks) 1. 2. 3. 4."}],"propPages":["asset:img43bae6e6381c4695c6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Monomorphic VT (rate approx. 215/min) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">10 x anti-tachycardia pacing spikes (rate approx. 240/min)  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Persistent VT following antitachycardia pacing (ICD sees new complexes as ‘normal’) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Conclusion : ICD malfunction – no shock delivered following antitachycardia pacing as </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">ICD does not recognise persistent VT </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Drug toxicity </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Electrolyte disturbances (ie, hypokalemia and hypomagnesemia) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">New or worsened heart failure </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Acute myocardial ischemia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Thyrotoxicosis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Infection </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\"> Use </span><span class=\"answer-source-red\"><strong>magnet</strong></span><span class=\"answer-source-red\"> to deactivate device (preserve battery life) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>External DC cardioversion</strong></span><span class=\"answer-source-red\"> 100-150-200J checking for resumption of SR after each shock </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">(analgesia with fentanyl 25mcg aliquots +/- midazolam 1-2mg) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Correct any electrolyte disturbance</strong></span><span class=\"answer-source-red\"> – aim K and Mg at upper limits of normal </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">(10mmol/L KCl over 30 minutes and 10mmol MgSO4 over 15 minutes) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Pharmacotherapy</strong></span><span class=\"answer-source-red\"> : If no signs of overt heart failure, reduce sympathetic drive with IV </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">betablocker (eg esmolol) ; stabilise myocardium with IV amiodarone (bolus followed by </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">infusion) </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"It is a busy Saturday evening in a tertiary ED where you are working as a junior FACEM. The NUM has received a call from the head of the local ambulance service informing them that a bomb has just gone off at a music concert. They have declared a major incident.","parts":[{"id":"a","label":"Part A","prompt":"Define the term ‘major incident’ when used in a medical context. (2 marks) You will be receiving > 40 casualties who have all sustained blast injuries."},{"id":"b","label":"Part B","prompt":"Complete the table below describing the 4 different categories of blast injuries with an example of each. (8 marks)"},{"id":"c","label":"Part C","prompt":"In additional to relevant clinical services, list (4) key individuals/services who should\n\nbe informed once a major incident has been declared. (4 marks)\n1. 2. 3. 4. As the consultant in charge, you are responsible for preparing the department to receive the casualties."},{"id":"d","label":"Part D","prompt":"Outline (4) key components of preparing the department. (4 marks) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">A major incident can be defined as any incident where the location, number, severity or </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">type of live casualties requires extraordinary resources. </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><span class=\"answer-source-red\">Overpressure wave </span></td><td><span class=\"answer-source-red\">PTX, hollow viscus perforation, TM </span></td><td></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">rupture </span></td></tr><tr><td><strong>Secondary </strong></td><td><span class=\"answer-source-red\">Airborne objects eg shrapnel </span></td><td><span class=\"answer-source-red\">Fractures, amputations, penetrating </span></td></tr><tr><td><span class=\"answer-source-red\">causing penetrating trauma </span></td><td><span class=\"answer-source-red\">injuries </span></td><td></td></tr><tr><td><strong>Tertiary </strong></td><td><span class=\"answer-source-red\">From being thrown by blast </span></td><td><span class=\"answer-source-red\">Fractures, head injuries </span></td></tr><tr><td><strong>Quaternary </strong></td><td><span class=\"answer-source-red\">Everything else resultant from </span></td><td><span class=\"answer-source-red\">Burns, asthma attacks, radiation </span></td></tr><tr><td><span class=\"answer-source-red\">blast </span></td><td><span class=\"answer-source-red\">effects </span></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Media liaison / public relations </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Security </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Staff</strong></span><span class=\"answer-source-red\">: allocate roles, form teams, call in extra staff or place on standby </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Supplies</strong></span><span class=\"answer-source-red\">: disaster packs, labels, equipment (dressings, splints etc), blood products, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">analgesia, IV access etc </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Space</strong></span><span class=\"answer-source-red\">: move patients out of the department, set up triage areas for walking wounded vs </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">ambulances, utilise other parts of hospital eg outpatient clinics and nonclinical areas </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>Systems</strong></span><span class=\"answer-source-red\">: activation of disaster plan including triage system, media and family liaisons </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"An 11-year-old boy is brought into your emergency department after his pelvis and lower\nabdomen were driven over by a semi-trailer. An X-ray is performed :","parts":[{"id":"a","label":"Part A","prompt":"List (4) relevant findings on the X-ray. (2 marks -1/2 mark each) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"List (5) complications of this injury. (5 marks) 1. 2. 3. 4. 5."},{"id":"c","label":"Part C","prompt":"Outline (5) steps in the management of the suspected injuries associated with this X- ray. (5 marks) 1. 2. 3. 4. 5."}],"propPages":["asset:imgfb05387f15153eb51a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">An 11-year-old boy is brought into your emergency department after his pelvis and lower</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">abdomen were driven over by a semi-trailer.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>An X-ray is performed : </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
